bg=2
colors=[[6,9],[8,7],[1,3]]
shapes={
6:[[6,2,2],[6,6,2],[2,2,6]],
9:[[2,2,9],[9,9,2],[2,2,9]],
8:[[8,2,8],[2,8,2],[8,8,8]],
7:[[7,7,7],[2,7,2],[7,7,2]],
1:[[2,1,2],[1,2,1],[1,1,1]],
3:[[3,3,2],[2,3,2],[2,3,3]],
}
out=[[bg]*13 for _ in range(19)]
for blockrow,row0 in enumerate([1,7,13]):
    for bi,col0 in enumerate([1,7]):
        color=colors[blockrow][bi]
        for i in range(5):
            for j in range(5):
                out[row0+i][col0+j]=color
        for i in range(3):
            for j in range(3):
                out[row0+1+i][col0+1+j] = bg if shapes[color][i][j]==color else color
print('\n'.join(' '.join(map(str,r)) for r in out))
print(len(out),len(out[0]))
